import os
import subprocess

def extract_chrome_passwords():
  """Extracts saved passwords from Chrome using the `chrome-password` command."""
  try:
    # Run the command to get passwords
    output = subprocess.check_output(["chrome-password", "--json"]).decode("utf-8")

    # Parse the JSON output and extract the passwords
    passwords = {}
    for line in output.splitlines():
      if "password" in line:
        key, value = line.split(":", 1)
        passwords[key] = value.strip()

    return passwords
  except FileNotFoundError:
